trace.command:
cd /workspace/graphic && cp js/template.js /tmp/orig.js && cat > /tmp/post.js <<'EOF'

// Reopen: a late bid. The stamp, the dim and the going tag leave from wherever they are, the
// pips go dark, and the card is back to live bidding.
function clearAuction() {
  gsap.to(['.bid-card-stamp', '.bid-card-dim', '.bid-card-tag'], { opacity: 0, duration: 0.3, ease: 'power2.out', overwrite: 'auto' });
  gsap.to(['.bid-card-pip-1', '.bid-card-pip-2'], { opacity: 0.25, duration: 0.3, overwrite: 'auto' });
  gsap.to('.bid-card-box', { scale: 1, duration: 0.3, overwrite: 'auto' });
  var tag = document.querySelector('.bid-card-tag');
  if (tag) tag.classList.remove('bid-card-twice');
}
EOF
{ cat /tmp/pre.js; echo; sed -n 53,68p /tmp/orig.js; cat /tmp/anim.js; sed -n '108,$p' /tmp/orig.js; cat /tmp/post.js; } > js/template.js
grep -n "== ANIMATION\|== END ANIM\|^var NOACG_ANIM\|^// ---- The interpreter" js/template.js
export NOACG_URL=https://noacg.studio; noacg validate /workspace/graphic --screenshots /workspace/shots 2>&1 | tail -60

cd /workspace && cat > /tmp/stress.json <<'EOF'
{"f0":"128","f1":"A week in a family-sized holiday cottage on the north Cornish coast, donated by the Hendersons in Year 4","f2":"12500","f3":"1047","logo":"bright: white crest"}
EOF
export NOACG_URL=https://noacg.studio; rm -rf /mnt/session/outputs/coverage; noacg coverage /workspace/graphic --stress /tmp/stress.json --out /mnt/session/outputs/coverage 2>&1 | tail -6; python3 -c "
import json;d=json.load(open('/mnt/session/outputs/coverage/coverage.json'))
print(d['valueSets']['long'])
for f in d['frames']: print(f['file'], f['values'], f['state'], f.get('machine'))
print(d.get('crops'), d.get('notes'), d.get('findings'))"
